"""Display optical flow arrows generated by SensorFunction."""

from __future__ import annotations

import sys
import traceback
from pathlib import Path

import numpy as np
from PyQt5 import QtCore, QtGui, QtWidgets

PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from api.algorithm.sensor_function import SensorFunction
from api.algorithm.touch_sensor import TouchSensor


FLOW_STEP = 35
FLOW_SCALE = 4.5


def frame_to_rgb_image(frame):
    if frame is None:
        return None
    image = np.asarray(frame, dtype=np.uint8)
    if image.ndim == 3 and image.shape[2] == 3:
        image = image[:, :, ::-1]
    return np.ascontiguousarray(image)


class FlowViewer(QtWidgets.QWidget):
    def __init__(self, sensor, functions, parent=None):
        super().__init__(parent)
        self.sensor = sensor
        self.functions = functions
        self._closed = False

        self.setWindowTitle("Tangential Flow Viewer")
        self.resize(800, 600)

        self.label = QtWidgets.QLabel()
        self.label.setAlignment(QtCore.Qt.AlignCenter)
        self.label.setMinimumSize(640, 480)
        self.label.setStyleSheet("background: #111; border: 1px solid #444;")

        layout = QtWidgets.QVBoxLayout()
        layout.setContentsMargins(12, 12, 12, 12)
        layout.addWidget(self.label)
        self.setLayout(layout)

        self.timer = QtCore.QTimer(self)
        self.timer.timeout.connect(self.update_frame)
        self.timer.start(33)

    def update_frame(self):
        try:
            self.sensor.update(2)
            flow_matrix = self.sensor.get_flow_matrix()
            frame = self.functions.flow_to_arrow_segments(
                flow_matrix,
                step=FLOW_STEP,
                scale=FLOW_SCALE,
            )
            self._set_label_image(frame_to_rgb_image(frame))
        except Exception as exc:
            print(f"Error: {exc}")
            traceback.print_exc()
            self.close()

    def _set_label_image(self, image):
        if image is None:
            return

        if image.ndim == 2:
            h, w = image.shape
            image_format = QtGui.QImage.Format_Grayscale8
        elif image.ndim == 3 and image.shape[2] == 3:
            h, w = image.shape[:2]
            image_format = QtGui.QImage.Format_RGB888
        else:
            return

        qimage = QtGui.QImage(
            image.data,
            w,
            h,
            image.strides[0],
            image_format,
        ).copy()
        pixmap = QtGui.QPixmap.fromImage(qimage).scaled(
            self.label.size(),
            QtCore.Qt.KeepAspectRatio,
            QtCore.Qt.SmoothTransformation,
        )
        self.label.setPixmap(pixmap)

    def keyPressEvent(self, event):
        if event.key() in (QtCore.Qt.Key_Q, QtCore.Qt.Key_Escape):
            self.close()
            return
        super().keyPressEvent(event)

    def closeEvent(self, event):
        if not self._closed:
            self._closed = True
            self.timer.stop()
            self.sensor.release()
        super().closeEvent(event)


def main():
    app = QtWidgets.QApplication.instance() or QtWidgets.QApplication(sys.argv)
    sensor = TouchSensor(usb_id=0)
    functions = SensorFunction()

    viewer = FlowViewer(sensor, functions)
    viewer.show()
    sys.exit(app.exec_())


if __name__ == "__main__":
    main()
